// I-40c. Logic: automation/lib/w20-ms.mjs (tested in automation/tests/W20.test.mjs). Needs NODE_FUNCTION_ALLOW_EXTERNAL=lv-automation, NODE_FUNCTION_ALLOW_BUILTIN=crypto and N8N_BLOCK_ENV_ACCESS_IN_NODE=false.
const M = require('lv-automation').w20ms;
const STATE_SECRET = $env.MS_OAUTH_STATE_SECRET || $env.INTERNAL_HMAC_SECRET;
const CFG = { clientId: $env.MS_GRAPH_CLIENT_ID, redirectUri: $env.MS_GRAPH_REDIRECT_URI, tenant: $env.MS_GRAPH_TENANT, stateSecret: STATE_SECRET, portalUrl: $env.PORTAL_URL, adminConsentRedirectUri: $env.MS_ADMIN_CONSENT_REDIRECT_URI || $env.PORTAL_URL };
const s = $('Called by W20 MS callback').first().json;
const row = { broker_id: s.broker_id, calendar_status: s.current_status };
let token = null; try { const t = $('MS token exchange').first().json; token = { statusCode: t.statusCode, body: t.body }; } catch (e) {}
const state = row.broker_id ? s.state : { ok: false, reason: 'unknown_broker' };
const plan = M.planCallback({ state, query: s.query, token, currentStatus: row.calendar_status, cfg: CFG });
// I-41j: the refresh token never leaves this node; only "Vault: prepare input" reads it, straight from the token response.
return [{ json: M.publicPlan({ broker_id: row.broker_id || null, ...plan }) }];

// I-40c. Logic: automation/lib/w20-ms.mjs (tested in automation/tests/W20.test.mjs). Needs NODE_FUNCTION_ALLOW_EXTERNAL=lv-automation, NODE_FUNCTION_ALLOW_BUILTIN=crypto and N8N_BLOCK_ENV_ACCESS_IN_NODE=false.
const M = require('lv-automation').w20ms;
const STATE_SECRET = $env.MS_OAUTH_STATE_SECRET || $env.INTERNAL_HMAC_SECRET;
const CFG = { clientId: $env.MS_GRAPH_CLIENT_ID, redirectUri: $env.MS_GRAPH_REDIRECT_URI, tenant: $env.MS_GRAPH_TENANT, stateSecret: STATE_SECRET, portalUrl: $env.PORTAL_URL, adminConsentRedirectUri: $env.MS_ADMIN_CONSENT_REDIRECT_URI || $env.PORTAL_URL };
// I-41j: the ONLY node output that carries the refresh token, and its only consumer is the vault RPC.
const p = $input.first().json;
let token = null; try { const t = $('MS token exchange').first().json; token = { statusCode: t.statusCode, body: t.body }; } catch (e) {}
return [{ json: M.vaultInput({ plan: p, token }) }];

// I-40c. Logic: automation/lib/w20-ms.mjs (tested in automation/tests/W20.test.mjs). Needs NODE_FUNCTION_ALLOW_EXTERNAL=lv-automation, NODE_FUNCTION_ALLOW_BUILTIN=crypto and N8N_BLOCK_ENV_ACCESS_IN_NODE=false.
const M = require('lv-automation').w20ms;
const STATE_SECRET = $env.MS_OAUTH_STATE_SECRET || $env.INTERNAL_HMAC_SECRET;
const CFG = { clientId: $env.MS_GRAPH_CLIENT_ID, redirectUri: $env.MS_GRAPH_REDIRECT_URI, tenant: $env.MS_GRAPH_TENANT, stateSecret: STATE_SECRET, portalUrl: $env.PORTAL_URL, adminConsentRedirectUri: $env.MS_ADMIN_CONSENT_REDIRECT_URI || $env.PORTAL_URL };
// I-43e: the ONLY output of this sub-workflow on success: the public plan (no refresh token) plus the vault reference.
const p = $('MS callback: plan').first().json;
return [{ json: { ...p, token_ref: $input.first().json.token_ref || null, vault: 'stored' } }];

// I-40c. Logic: automation/lib/w20-ms.mjs (tested in automation/tests/W20.test.mjs). Needs NODE_FUNCTION_ALLOW_EXTERNAL=lv-automation, NODE_FUNCTION_ALLOW_BUILTIN=crypto and N8N_BLOCK_ENV_ACCESS_IN_NODE=false.
const M = require('lv-automation').w20ms;
const STATE_SECRET = $env.MS_OAUTH_STATE_SECRET || $env.INTERNAL_HMAC_SECRET;
const CFG = { clientId: $env.MS_GRAPH_CLIENT_ID, redirectUri: $env.MS_GRAPH_REDIRECT_URI, tenant: $env.MS_GRAPH_TENANT, stateSecret: STATE_SECRET, portalUrl: $env.PORTAL_URL, adminConsentRedirectUri: $env.MS_ADMIN_CONSENT_REDIRECT_URI || $env.PORTAL_URL };
// I-41j: vault RPC failed after a good exchange. Built fresh (no input fields are copied, so nothing secret flows on).
const p = $('MS callback: plan').first().json;
const row = { calendar_status: $('Called by W20 MS callback').first().json.current_status };
return [{ json: { ...M.planVaultFailure({ brokerId: p.broker_id, currentStatus: row.calendar_status, cfg: CFG }), vault: 'failed' } }];

// I-40c. Logic: automation/lib/w20-ms.mjs (tested in automation/tests/W20.test.mjs). Needs NODE_FUNCTION_ALLOW_EXTERNAL=lv-automation, NODE_FUNCTION_ALLOW_BUILTIN=crypto and N8N_BLOCK_ENV_ACCESS_IN_NODE=false.
const M = require('lv-automation').w20ms;
const STATE_SECRET = $env.MS_OAUTH_STATE_SECRET || $env.INTERNAL_HMAC_SECRET;
const CFG = { clientId: $env.MS_GRAPH_CLIENT_ID, redirectUri: $env.MS_GRAPH_REDIRECT_URI, tenant: $env.MS_GRAPH_TENANT, stateSecret: STATE_SECRET, portalUrl: $env.PORTAL_URL, adminConsentRedirectUri: $env.MS_ADMIN_CONSENT_REDIRECT_URI || $env.PORTAL_URL };
// Nothing to store (error, cancel, consent pending, no code): pass the public plan on.
return [{ json: { ...$input.first().json, vault: 'n/a' } }];
